import os
os.makedirs("data/raw", exist_ok=True)
os.makedirs("data/processed", exist_ok=True)

#  6 ACCESSIONS  - pqqD genes (276bp) 
your_ids = {
 "KM251420.1": "",
 "CP003080.1": "",
 "CP023065.1": "",
 "CP077007.1": "",
 "CP125543.1": "",
 "CP003685.1": ""
}

# Save to raw and processed
with open("data/processed/combined_pqqD.fasta", "w") as out:
    for acc, seq in your_ids.items():
        out.write(f">{acc} pqqD gene {len(seq)}bp\n{seq}\n")
        with open(f"data/raw/{acc}.fasta", "w") as f:
            f.write(f">{acc} pqqD gene {len(seq)}bp\n{seq}\n")

print(f"DONE! 6 files saved with YOUR accessions")
for k,v in your_ids.items():
    print(k, len(v), "bp")